     */
    public static function obtenerObjElementoSalarialDadoId($idelementosalarial) {
        return Doctrine::getTable('ConfigElementoSalarialCargo')->find($idelementosalarial);
    }
    
    public static function obtenerCantidadTotalElemSalCargo($idcargo) {

        //Devolviendo la cantidad total de los salarios especificos.
        return Doctrine_Query::create()->select('COUNT(idelementosalarialcargo) AS cantidad')
                        ->from('ConfigElementoSalarialCargo')
                        ->where('idcargo = ?', array($idcargo))
                        ->fetchOne()
                        ->cantidad;
   }
   
