   public static function existeConfElementoSalarialCargoXIdCargo($idcargo) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('ConfigElementoSalarialCargo p')
                ->where("p.idcargo=?", array($idcargo))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 2;
		 }
     }
   
