   public static function getInfoElementoSalarialService($idcargo) {
        $sqlData = "select elem.idelementosalarialcargo, elem.idsistemapago, sist.denominacion, elem.idperiodopago, ppago.denominacion, elem.idgrupoescala, 
		                   gesc.denominacion, elem.idsectorsalarial, nsec.denominacion, elem.importe, elem.idperiodopago, elem.idgrupoescala, elem.idsectorsalarial	
						   from mod_nomina.conf_elementosalarialcargo elem 
									inner join mod_nomina.nom_sistemapago sist on (sist.idsistemapago = elem.idsistemapago)
									inner join mod_nomina.nom_periodopago ppago on (ppago.idperiodopago = elem.idperiodopago)
									inner join mod_nomina.nom_grupoescala gesc on (gesc.idgrupoescala = elem.idgrupoescala)
									inner join mod_nomina.nom_sectorsalarial nsec on (nsec.idsectorsalarial = elem.idsectorsalarial)
									where elem.idcargo;";
					    $mg = Doctrine_Manager::getInstance();
					    $conn = $mg->getCurrentConnection();
		$arrData = $conn->fetchAll($sqlData, array($idcargo));
		return $arrData;	  
   }



   public function obtenerconfiguracionesESC($arridscargos){
        $sql = "select idcargo from mod_nomina.conf_elementosalarialcargo where idcargo in (".implode(",",$arridscargos).");";
       $mg = Doctrine_Manager::getInstance();
       $conn = $mg->getCurrentConnection();
       $arrData = $conn->fetchAll($sql);
       return $arrData;
   }

   public function obtenerconfiguracionesESCPlantillaNominal($arridscargos){
        $sql = "select pn.denominacion,pnc.idcargo,pn.idplantillanominal from  mod_nomina.conf_plantillanominalcargo pnc 
        inner  join mod_nomina.conf_plantillanominal pn on (pn.idplantillanominal = pnc.idplantillanominal)
        where pnc.idcargo in (".implode(",",$arridscargos).");";
               $mg = Doctrine_Manager::getInstance();
       $conn = $mg->getCurrentConnection();
       $arrData = $conn->fetchAll($sql);
       return $arrData;
   }

